#Cargamos librerías principales

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt

#Cargamos el modelo
import pickle
filename = 'modelo-tree.pkl'
modelo, min_max_scaler, variables = pickle.load(open(filename, 'rb'))

# Cargamos los datos futuros, tengo 5 clientes y quiero saber cuanta plata me va a gastar cada uno de ellos.
# data = pd.read_csv("videojuegos-datosFuturos.csv") # para convertirlos en formulario web esto lo ponemos como comentario.
# data.head()

# Interface grafica.
#Interfaz gráfica


#Se crea interfaz gráfica con streamlit para captura de los datos

import streamlit as st

st.title('Predicción de inversión en una tienda de videojuegos')

Edad = st.slider('Edad', min_value=14, max_value=52, value=20, step=1)
videojuego = st.selectbox('Videojuego', ["'Mass Effect'","'Battlefield'", "'Fifa'","'KOA: Reckoning'","'Crysis'","'Sim City'","'Dead Space'","'F1'"])
Plataforma = st.selectbox('Plataforma', ["'Play Station'", "'Xbox'","PC","Otros"])
Sexo = st.selectbox('Sexo', ['Hombre', 'Mujer'])
Consumidor_habitual = st.selectbox('Consumidor_habitual', ['True', 'False'])


#Dataframe
datos = [[Edad, videojuego,Plataforma,Sexo,Consumidor_habitual]]
data = pd.DataFrame(datos, columns=['Edad', 'videojuego','Plataforma','Sexo','Consumidor_habitual']) #Dataframe con los mismos nombres de variables

# Preparación de los datos.

#Se realiza la preparación de datos
data_preparada=data.copy()

#En despliegue drop_first= False
data_preparada = pd.get_dummies(data_preparada, columns=['videojuego', 'Plataforma','Sexo', 'Consumidor_habitual'], drop_first=False, dtype=int)
data_preparada.head()

#Se adicionan las columnas faltantes # es decir para poder que las variables de entrenamiento coincidan con las actuales, asi en mi set de datos actual, no tenga juegos que use cuando entrene, si no existe la creo, si exite la quita.
data_preparada=data_preparada.reindex(columns=variables,fill_value=0)
data_preparada.head()

# """Como yo seleccione un arbol no aplica esta normalización que viene a continuación, si hubiera elegido, red neuronal, knn, msv o regresion entonces si tuviera que normalizar."""

#Se normaliza la edad para predecir con Knn, Red, SVM, Reg
#En los despliegues no se llama fit

# data_preparada[['Edad']]= min_max_scaler.transform(data_preparada[['Edad']])
# data_preparada.head()

"""# Predicciones"""

#Hacemos la predicción con el Tree
Y_pred = modelo.predict(data_preparada)
print(Y_pred)

data['Prediccion']=Y_pred
data.head()

data

# Recordar medida de error del modelo

